/**
     * Create an (essentially) empty row; the row still has 1 placeholder attribute since plans with empty schemas are pruned.
     */
    // TODO: cherry-picked from https://github.com/elastic/elasticsearch/pull/105454/commits/9c5810d51cc5f6827a2cffcffca2c8dbf883fde7
    // Avoid duplication once https://github.com/elastic/elasticsearch/pull/105454 is merged.
    private static LocalRelation emptyRow(Source source) {
        Block block = SINGLE_NULL_VALUE;
        block.incRef();
        return new LocalRelation(source, List.of(new EmptyAttribute(Source.EMPTY)), LocalSupplier.of(new Block[] { block }));
    }

pl = plan.transformDown(p -> {
                // skip nodes that simply pass the input through
                if (p instanceof Limit) {
                    return p;
                }

                // remember used
                boolean recheck;
                // analyze the unused items against dedicated 'producer' nodes such as Eval and Aggregate
                // perform a loop to retry checking if the current node is completely eliminated
                do {
                    recheck = false;
                    if (p instanceof Aggregate aggregate) {
                        var remaining = seenProjection.get() ? removeUnused(aggregate.aggregates(), used) : null;

                        if (remaining != null) {
                            if (remaining.isEmpty()) {
                                // We still need to have a plan that produces 1 row per group.
                                if (aggregate.groupings().isEmpty()) {
                                    p = emptyRow(aggregate.source());
                                } else {
                                    // Aggs cannot produce pages with 0 columns, so retain one grouping.
                                    remaining = List.of((NamedExpression) aggregate.groupings().get(0));
                                    p = new Aggregate(aggregate.source(), aggregate.child(), aggregate.groupings(), remaining);
                                }
                            } else {
                                p = new Aggregate(aggregate.source(), aggregate.child(), aggregate.groupings(), remaining);
                            }
                        }

                        seenProjection.set(Boolean.TRUE);
                    } else if (p instanceof Eval eval) {
                        var remaining = seenProjection.get() ? removeUnused(eval.fields(), used) : null;
                        // no fields, no eval
                        if (remaining != null) {
                            if (remaining.isEmpty()) {
                                p = eval.child();
                                recheck = true;
                            } else {
                                p = new Eval(eval.source(), eval.child(), remaining);
                            }
                        }
                    } else if (p instanceof Project) {
                        seenProjection.set(Boolean.TRUE);
                    }
                } while (recheck);

                used.addAll(p.references());

                // preserve the state before going to the next node
                return p;
            })

/**
     * Expects
     *
     * EsqlProject[[x{r}#7]]
     * \_Eval[[1[INTEGER] AS x]]
     *   \_Limit[1000[INTEGER]]
     *     \_Aggregate[[emp_no{f}#10],[emp_no{f}#10]]
     *       \_EsRelation[test][_meta_field{f}#16, emp_no{f}#10, first_name{f}#11, ..]
     */
    public void testEmptyProjectInStatWithGroupAndEval() {
        var plan = plan("""
            from test
            | stats c = count(salary) by emp_no
            | eval x = 1
            | drop c, emp_no
            """);

        var project = as(plan, Project.class);
        var eval = as(project.child(), Eval.class);
        var limit = as(eval.child(), Limit.class);
        var agg = as(limit.child(), Aggregate.class);
        var relation = as(agg.child(), EsRelation.class);
        assertThat(Expressions.names(agg.groupings()), contains("emp_no"));
        assertThat(Expressions.names(agg.aggregates()), contains("emp_no"));

        var exprs = eval.fields();
        assertThat(exprs.size(), equalTo(1));
        var alias = as(exprs.get(0), Alias.class);
        assertThat(alias.name(), equalTo("x"));
        assertThat(alias.child().fold(), equalTo(1));
    }

/**
